// AUDIT 2026-07-03 (perf) — WebP-with-fallback image.
//
// Serves the WebP variant (generated by scripts/webp-convert.mjs, ~32% smaller)
// to modern browsers and falls back to the original JPG for old Safari/iOS.
// Drop-in for a plain <img src="/foo.jpg">: same visual output, smaller payload.
// The webp path is derived from the jpg path, so every public/*.jpg that has a
// matching *.webp is upgraded automatically; anything without a .webp still
// renders via the <img> fallback (no broken image).

import type { ImgHTMLAttributes } from 'react';

interface PictureImgProps extends ImgHTMLAttributes<HTMLImageElement> {
  src: string;
}

export function PictureImg({ src, className, ...imgProps }: PictureImgProps) {
  const webp = /\.(jpe?g)$/i.test(src) ? src.replace(/\.(jpe?g)$/i, '.webp') : null;
  // `display: contents` makes <picture> generate NO layout box, so the inner
  // <img>'s sizing classes (w-full/h-full/object-cover/absolute-fill) resolve
  // against the ORIGINAL parent container exactly as a bare <img> did — no layout
  // change. Without this, <picture>'s default `display:inline` shrinks to content
  // and the hero background stops covering. Supported in Safari 11.1+ / iOS 14.
  //
  // CSP 2026-10-29 — it is a Tailwind class (`contents`), NOT `style={{}}`:
  // prerender-body.mjs serializes a style prop as an HTML `style=""` attribute,
  // which `style-src 'self'` blocks at parse time (one console error per
  // <picture>, and no `display:contents` until React mounts). A class resolves
  // from the bundled stylesheet, so the prerendered HTML lays out correctly.
  return (
    <picture className="contents">
      {webp && <source srcSet={webp} type="image/webp" />}
      <img src={src} className={className} {...imgProps} />
    </picture>
  );
}
